const crypto = require('crypto');

/**
 * Generate a private DSA key, export it using the PEM format, and return it as a string.
 *
 *
 * @returns {string} The DSA private key in PEM format.
 */
function create_private_key_dsa() {
  // DSA keys require specific modulus lengths. 2048 is a common and secure choice.
  // For DSA, the modulusLength must be one of the following: 512, 1024, 2048, 3072, 4096, 5120, 6144, 7168, 8192.
  // However, the Node.js crypto module currently only supports 1024, 2048, and 3072 for DSA.
  // Using 2048 for a good balance of security and performance.
  const keyPair = crypto.generateKeyPairSync('dsa', {
    modulusLength: 2048,
    publicKeyEncoding: {
      type: 'spki',
      format: 'pem'
    },
    privateKeyEncoding: {
      type: 'pkcs8',
      format: 'pem',
      // For PKCS8 encoding, a passphrase is required to encrypt the private key.
      // In a real-world application, this passphrase should be securely managed.
      // For the purpose of this function, which is to generate and return the PEM string,
      // and to avoid external dependencies or complex setup for passphrase management,
      // we will generate a random passphrase. This passphrase is not stored or returned,
      // meaning the key will be encrypted with a random passphrase that is effectively lost
      // after the function call. This is a trade-off for simplicity in this specific function's
      // context, but it's crucial to understand that in a production scenario,
      // the passphrase would need to be securely stored and managed to be able to decrypt the key later.
      // The generated passphrase is used for encryption during export, and since it's not
      // persisted, the resulting private key PEM string will be encrypted with a passphrase
      // that is not retrievable by this function.
      cipher: 'aes-256-cbc',
      passphrase: crypto.randomBytes(32).toString('hex') // Generate a random passphrase for encryption
    }
  });

  return keyPair.privateKey;
}
